SELECT male_icu_patients_first_48_hours.hadm_id, male_icu_patients_first_48_hours.stay_id, male_icu_patients_first_48_hours.first_careunit, male_icu_patients_first_48_hours.last_careunit, male_icu_patients_first_48_hours.intime, male_icu_patients_first_48_hours.outtime, male_icu_patients_first_48_hours.los, male_icu_patients_first_48_hours.gender, male_icu_patients_first_48_hours.anchor_age, male_icu_patients_first_48_hours.anchor_year, male_icu_patients_first_48_hours.anchor_year_group, male_icu_patients_first_48_hours.icd_code, male_icu_patients_first_48_hours.icd_version, male_icu_patients_first_48_hours.procedure_code, male_icu_patients_first_48_hours.procedure_version, male_icu_patients_first_48_hours.value, male_icu_patients_first_48_hours.valueuom, male_icu_patients_first_48_hours.test_itemid, male_icu_patients_first_48_hours.test_name, male_icu_patients_first_48_hours.isolate_num, male_icu_patients_first_48_hours.quantity, male_icu_patients_first_48_hours.ab_itemid, male_icu_patients_first_48_hours.ab_name, male_icu_patients_first_48_hours.dilution_text, male_icu_patients_first_48_hours.dilution_comparison, male_icu_patients_first_48_hours.dilution_value, male_icu_patients_first_48_hours.interpretation FROM male_icu_patients_first_48_hours WHERE male_icu_patients_first_48_hours.hadm_id IN (SELECT male_icu_patients_first_48_hours.hadm_id FROM male_icu_patients_first_48_hours JOIN male_icu_controls ON male_icu_patients_first_48_hours.hadm_id = male_icu_controls.hadm_id WHERE male_icu_controls.gender = male_icu_patients_first_48_hours.gender AND male_icu_controls.anchor_age = male_icu_patients_first_48_hours.anchor_age AND male_icu_controls.anchor_year = male_icu_patients_first_48_hours.anchor_year AND male_icu_controls.anchor_year_group = male_icu_patients_first_48_hours.anchor_year_group) ORDER BY male_icu_patients_first_48_hours.hadm_id NULLS LAST;